/* Traqqr website motion · v1 · 3 Nov 2026
   The motion pieces for the internal pages, as one dependency-free ES module.
   Source of truth for motion: the artifact "Traqqr Internal Pages Motion" (https://claude.ai/artifact/2EeQnzdvaEZyppRNcBhKh6).
   Curves and verbs come from the Traqqr motion-graphics system (shared/motion/GRAMMAR.md, docs/web.md).

   Use:
     <div data-tq-motion="integrations-hub"></div>
     import { mountAll } from './traqqr-motion.js'; mountAll();
   Every piece draws on a fixed design-size stage (e.g. 1200×500) scaled to the element's width.
   Language: taken from <html lang> ("en…" → EN, everything else → DE), or mountAll({ lang: 'en' }).
   Loops only run while on screen; "once" pieces play the first time they are 35% in view; scroll pieces follow scroll.
   prefers-reduced-motion: every piece shows its finished state and nothing moves. */

const STYLE_ID = 'tq-motion-css';
const CSS = `
.tq-m { --bg:#0c0a09; --card:#1c1917; --muted:#292524; --fg:#fafaf9; --mfg:#a6a09b; --brand:#ffb74d; --cta:#f59e0b;
  --ok:#4ade80; --ok-bg:rgba(74,222,128,.14); --line:rgba(255,255,255,.10); --line2:rgba(255,255,255,.16); --glass:rgba(28,25,23,.62);
  --sans: var(--font-sans, "Manrope", ui-sans-serif, system-ui, sans-serif); --mono: var(--font-mono, "Space Mono", ui-monospace, Menlo, monospace);
  position: relative; width: 100%; }
.tq-fit { position: relative; width: 100%; overflow: visible; }
.tq-stage { position: absolute; left: 0; top: 0; transform-origin: 0 0; }
.tq-scrolly { position: relative; height: var(--tq-scroll-h, 240vh); }
.tq-sticky { position: sticky; top: var(--tq-sticky-top, max(96px, calc(50vh - 300px))); }
/* ---- shared parts inside stages ---- */
.s * { box-sizing: border-box; }
.s { color: var(--fg); font-family: var(--sans); }
.gcard { position: absolute; background: var(--glass); border: 1px solid var(--line); border-radius: 14px;
  -webkit-backdrop-filter: blur(24px); backdrop-filter: blur(24px); box-shadow: inset 0 1px 0 rgba(255,255,255,.06); }
.badge { display: inline-flex; align-items: center; height: 22px; padding: 0 9px; border-radius: 26px; font: 400 11px/1 var(--mono);
  border: 1px solid var(--line2); color: var(--fg); white-space: nowrap; will-change: transform, opacity, filter; }
.badge.sec { background: var(--muted); border-color: transparent; }
.badge.ok { background: var(--ok-bg); color: var(--ok); border-color: transparent; }
.ico { width: 16px; height: 16px; flex: none; stroke: currentColor; fill: none; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.tile { width: 58px; height: 58px; display: block; }
.mut { color: var(--mfg); }
.abs { position: absolute; }
.will { will-change: transform, opacity, filter; }
`;

