  phone: '<rect width="14" height="20" x="5" y="2" rx="2"/><path d="M12 18h.01"/>', tablet: '<rect width="16" height="20" x="4" y="2" rx="2"/><path d="M12 18h.01"/>',
  laptop: '<path d="M18 5a2 2 0 0 1 2 2v8.5a1 1 0 0 1-.5.9l-.1.05H4.6l-.1-.05a1 1 0 0 1-.5-.9V7a2 2 0 0 1 2-2Z"/><path d="M2 20h20"/>',
  lock: '<rect width="18" height="11" x="3" y="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/>', tag: '<path d="M12.6 2.6A2 2 0 0 0 11.2 2H4a2 2 0 0 0-2 2v7.2a2 2 0 0 0 .6 1.4l8.7 8.7a2.4 2.4 0 0 0 3.4 0l6.6-6.6a2.4 2.4 0 0 0 0-3.4z"/><circle cx="7.5" cy="7.5" r=".5" fill="currentColor"/>',
