/* ---------- mounting + one shared clock ---------- */
const LIVE = new Set();
let raf = 0;
function tick(now) {
  raf = LIVE.size ? requestAnimationFrame(tick) : 0;
  for (const p of LIVE) {
    LANG = p.lang;
    if (REDUCED) { if (!p.done) { p.render(p.mode === 'scroll' ? 1 : p.rest); p.done = true; } continue; }
    if (p.mode === 'scroll') {
      const r = p.track.getBoundingClientRect(), vh = innerHeight, k = cl(-r.top / Math.max(1, r.height - vh * .9));
      if (k !== p.lastK) { p.render(k); p.lastK = k; }
      continue;
    }
    const dt = p.last == null ? 0 : Math.min(.05, (now - p.last) / 1000); p.last = now;
    if (!p.visible || document.hidden) { p.last = null; continue; }
    if (p.mode === 'loop') { p.t = (p.t + dt) % p.dur; p.render(p.t); }
    else if (p.started) { p.t = Math.min(p.dur, p.t + dt); p.render(p.t); }
  }
}

