  const [SW, SH] = def.size;
  el.classList.add('tq-m');
  const fit = h('div', { class: 'tq-fit', style: `aspect-ratio:${SW}/${SH}` });
  const st = h('div', { class: 'tq-stage s', style: `width:${SW}px;height:${SH}px` }); fit.appendChild(st);
  let track = null;
  if (def.mode === 'scroll' && !opts.track) {
    track = h('div', { class: 'tq-scrolly' }, [h('div', { class: 'tq-sticky' }, [fit])]); el.appendChild(track);
  } else { el.appendChild(fit); track = opts.track || null; }
  LANG = lang;
  const p = { id, lang, mode: def.mode, dur: def.dur, rest: def.rest ?? def.dur, t: 0, started: false, visible: false, last: null, track };
  p.render = def.build(st);
  p.render(def.mode === 'scroll' ? 0 : 0);
  const ro = new ResizeObserver(() => { st.style.transform = `scale(${fit.clientWidth / SW})`; }); ro.observe(fit);
